using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Qms.Domain.Trainings;
namespace Qms.Infrastructure.Persistence.Configurations;
public sealed class TrainingAssignmentConfiguration:IEntityTypeConfiguration<TrainingAssignment>{public void Configure(EntityTypeBuilder<TrainingAssignment>b){b.ToTable("assignment","training");b.HasKey(x=>x.Id);b.Property(x=>x.EmployeeName).HasMaxLength(200).IsRequired();b.Property(x=>x.Position).HasMaxLength(160).IsRequired();b.Property(x=>x.CourseCode).HasMaxLength(80).IsRequired();b.Property(x=>x.CourseTitle).HasMaxLength(240).IsRequired();b.Property(x=>x.AssessmentMode).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.DeliveryMethod).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.PassingScore).HasPrecision(5,2);b.Property(x=>x.SessionCode).HasMaxLength(80);b.Property(x=>x.Trainer).HasMaxLength(160);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.AcknowledgementMeaning).HasMaxLength(500);b.Property(x=>x.TrainerApprovalNote).HasMaxLength(2000);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.QualityRecordId).IsUnique();b.HasIndex(x=>new{x.EmployeeUserId,x.Status,x.DueAtUtc});b.HasIndex(x=>x.PositionId);b.HasIndex(x=>x.DocumentTrainingRequirementId).HasFilter("\"DocumentTrainingRequirementId\" IS NOT NULL");b.HasOne<Qms.Domain.QualityRecords.QualityRecord>().WithMany().HasForeignKey(x=>x.QualityRecordId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.EmployeeUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Domain.Organization.Position>().WithMany().HasForeignKey(x=>x.PositionId).OnDelete(DeleteBehavior.Restrict);b.HasOne<TrainingMatrixRule>().WithMany().HasForeignKey(x=>x.MatrixRuleId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Domain.Documents.ControlledDocument>().WithMany().HasForeignKey(x=>x.ControlledDocumentId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Domain.Documents.DocumentTrainingRequirement>().WithMany().HasForeignKey(x=>x.DocumentTrainingRequirementId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Attempts).WithOne().HasForeignKey(x=>x.TrainingAssignmentId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Attempts).UsePropertyAccessMode(PropertyAccessMode.Field);}}
